const body = $input.first().json.body || $input.first().json;

// Custom Function tool format (message.toolCallList) — supported in case you switch to this later
const toolCall = body.message?.toolCallList?.[0];
if (toolCall) {
  return [{
    json: {
      toolCallId: toolCall.id,
      functionName: toolCall.function?.name || '',
      args: toolCall.function?.arguments || {}
    }
  }];
}

// API Request tool format — Vapi sends the raw params directly, no function name field.
// Infer which of the 4 tools was called based on which params are present.
// Check escalate_to_human FIRST since it can also carry caller_name/phone, which would otherwise collide with book_appointment.
let functionName = '';
if ('reason' in body || 'urgency' in body || 'sentiment_flag' in body) {
  functionName = 'escalate_to_human';
} else if ('caller_name' in body || 'slot_time' in body) {
  functionName = 'book_appointment';
} else if ('insurance_provider' in body) {
  functionName = 'check_insurance';
} else if ('appointment_type' in body) {
  functionName = 'check_availability';
}

return [{
  json: {
    toolCallId: 'direct-call',
    functionName,
    args: body
  }
}];

const item = $input.first().json;
const args = item.args;

const durations = { cleaning: 30, filling: 45, 'root canal': 90, extraction: 60, checkup: 20, whitening: 45 };
const type = (args.appointment_type || 'cleaning').toLowerCase();
const duration = durations[type] || 30;

// MOCK slots — swap for real Google Calendar availability lookup
const mockSlots = ['tomorrow at 10:00 AM', 'tomorrow at 2:30 PM', 'Thursday at 9:00 AM'];

return [{
  json: {
    toolCallId: item.toolCallId,
    result: `For a ${type} appointment, which takes about ${duration} minutes, we have openings ${mockSlots.join(', ')}.`
  }
}];

const item = $input.first().json;
const args = item.args;

const inNetworkPlans = ['delta dental', 'cigna dental', 'metlife', 'aetna dental', 'guardian'];
const provider = (args.insurance_provider || '').toLowerCase();
const inNetwork = inNetworkPlans.some(p => provider.includes(p));

let resultText;
if (!provider) {
  resultText = "I didn't catch the insurance provider name — could you repeat it?";
} else if (inNetwork) {
  resultText = `Good news — ${args.insurance_provider} is in-network with us.`;
} else {
  resultText = `I'm not seeing ${args.insurance_provider} as in-network on my end, but our front desk will confirm your exact coverage before your visit.`;
}

return [{ json: { toolCallId: item.toolCallId, result: resultText } }];

const item = $input.first().json;
const args = item.args;

return [{
  json: {
    toolCallId: item.toolCallId,
    caller_name: args.caller_name || 'Unknown',
    phone: args.phone || '',
    appointment_type: (args.appointment_type || 'cleaning').toLowerCase(),
    slot_time: args.slot_time || 'unspecified',
    insurance_provider: args.insurance_provider || ''
  }
}];

const item = $input.first().json;

return [{
  json: {
    toolCallId: item.toolCallId,
    result: `You're booked for a ${item.appointment_type} appointment ${item.slot_time}. We'll send a confirmation text to ${item.phone}.`
  }
}];

const item = $input.first().json;

return [{
  json: {
    result: item.result
  }
}];

const item = $input.first().json;
const args = item.args;

return [{
  json: {
    toolCallId: item.toolCallId,
    caller_name: args.caller_name || 'Unknown',
    phone: args.phone || '',
    reason: args.reason || '',
    urgency: args.urgency || 'urgent',
    sentiment_flag: args.sentiment_flag || 'neutral',
    appointment_type: args.appointment_type || '',
    insurance_provider: args.insurance_provider || ''
  }
}];

const item = $input.first().json;

return [{
  json: {
    toolCallId: item.toolCallId,
    result: "I've flagged this for our team — someone will reach out to you directly as soon as possible."
  }
}];

const body = $input.first().json.body || $input.first().json;

return [{
  json: {
    reviewId: body.reviewId || body.id || 'unknown',
    eventType: body.type || body.event || 'unknown',
    decision: body.status || body.decision || body.result || 'unknown',
    rawPayload: JSON.stringify(body)
  }
}];
